INSERT INTO monster VALUES (98,'Dog, Riding','Dog, Riding',NULL,'Medium','Animal',NULL,'2d8+4 (13 hp)','+2','40 ft. (8 squares)','16 (+2 Dex, +4 natural), touch 12, flat-footed 14','+1','+3','Bite +3 melee (1d6+3)','Bite +3 melee (1d6+3)','5 ft.','5 ft.','-','Low-light vision, scent','Fort +5, Ref +5, Will +1','Str 15, Dex 15, Con 15, Int 2, Wis 12, Cha 6','Jump +8, Listen +5, Spot +5, Swim +3, Survival +1*','Track','Alertness',NULL,'Temperate plains','Solitary or pack (5-12)','1',NULL,NULL,'-','-','','Riding dog; CR 1; Medium animal; HD 2d8+4; hp 13; Init +2; Spd 40 ft. (8 squares); AC 16 (+2 dex, +4 natural), touch 12, flat-footed 14; Base Atk +1; Grp +3; Atk +3 melee (1d6+3, bite); Full Atk +3 melee (1d6+3, bite); Space/Reach 5 ft./5 ft.; SA -; SQ Low-light vision, scent; AL N; SV Fort +5, Ref +5, Will +1; Str 15, Dex 15, Con 15, Int 2, Wis 12, Cha 6\n\nSkills and Feats: Jump +8, Listen +5, Spot +5, Swim +3, Survival +1*; Alertness, Track','\n      <div topic=\"Dog, Riding\" level=\"2\"><p><h2>Dog, Riding</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Dog, Riding</b><br/></td> \n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Medium Animal<br/></td> \n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>2d8+4 (13 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>40 ft. (8 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>16 (+2 Dex, +4 natural), touch 12, flat-footed 14<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+1/+3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Bite +3 melee (1d6+3)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Bite +3 melee (1d6+3)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>5 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Low-light vision, scent<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +5, Ref +5, Will +1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 15, Dex 15, Con 15, Int 2, Wis 12, Cha 6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Jump +8, Listen +5, Spot +5, Swim +3, Survival +1*<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Alertness, Track <sup>B</sup><br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Temperate plains<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary or pack (5-12)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>This category includes working breeds such as collies, huskies, and St. Bernards.</p><div topic=\"Carrying Capacity\" level=\"8\"><p><b>Carrying Capacity:</b> A light load for a riding dog is up to 100 pounds; a medium load, 101-200 pounds; and a heavy load, 201-300 pounds. A riding dog can drag 1,500 pounds.</p>\n</div><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>If trained for war, these animals can make trip attacks just as wolves do (see the Wolf entry). A riding dog can fight while carrying a rider, but the rider cannot also attack unless he or she succeeds on a Ride check.</p><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> Riding dogs have a +4 racial bonus on Jump checks. *Riding dogs have a +4 racial bonus on Survival checks when tracking by scent.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersAnimals');
INSERT INTO monster VALUES (99,'Donkey','Donkey',NULL,'Medium','Animal',NULL,'2d8+2 (11 hp)','+1','30 ft. (6 squares)','13 (+1 Dex, +2 natural), touch 11, flat-footed 12','+1','+1','Bite +1 melee (1d2)','Bite +1 melee (1d2)','5 ft.','5 ft.','-','Low-light vision, scent','Fort +4, Ref +4, Will +0','Str 10, Dex 13, Con 12, Int 2, Wis 11, Cha 4','Balance +3, Listen +3, Spot +2',NULL,'Endurance',NULL,'Temperate deserts','Solitary','1/6',NULL,NULL,'-','-','','Donkey; CR 1/6; Medium animal; HD 2d8+2; hp 11; Init +1; Spd 30 ft. (6 squares); AC 13 (+1 dex, +2 natural), touch 11, flat-footed 12; Base Atk +1; Grp +1; Atk +1 melee (1d2, bite); Full Atk +1 melee (1d2, bite); Space/Reach 5 ft./5 ft.; SA -; SQ Low-light vision, scent; AL N; SV Fort +4, Ref +4, Will +0; Str 10, Dex 13, Con 12, Int 2, Wis 11, Cha 4\n\nSkills and Feats: Balance +3, Listen +3, Spot +2; Endurance','\n      <div topic=\"Donkey\" level=\"2\"><p><h2>Donkey</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Donkey</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Medium Animal<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>2d8+2 (11 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>30 ft. (6 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>13 (+1 Dex, +2 natural), touch 11, flat-footed 12<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+1/+1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Bite +1 melee (1d2)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Bite +1 melee (1d2)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>5 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Low-light vision, scent<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +4, Ref +4, Will +0<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 10, Dex 13, Con 12, Int 2, Wis 11, Cha 4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Balance +3, Listen +3, Spot +2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Endurance<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Temperate deserts<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>1/6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>These long-eared, horselike creatures are surefooted and sturdy. The statistics presented here could also describe burros.</p><div topic=\"Carrying Capacity\" level=\"8\"><p><b>Carrying Capacity:</b> A light load for a donkey is up to 50 pounds; a medium load, 51-100 pounds; and a heavy load, 101-150 pounds. A donkey can drag 750 pounds.</p>\n</div><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>A donkey bites only when it has no way to escape.</p><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> Donkeys have a +2 racial bonus on Balance checks.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersAnimals');
INSERT INTO monster VALUES (100,'Eagle','Eagle',NULL,'Small','Animal',NULL,'1d8+1 (5 hp)','+2','10 ft. (2 squares), fly 80 ft. (average)','14 (+1 size, +2 Dex, +1 natural), touch 13, flat-footed 12','+0','-4','Talons +3 melee (1d4)','2 talons +3 melee (1d4) and bite -2 melee (1d4)','5 ft.','5 ft.','-','Low-light vision','Fort +3, Ref +4, Will +2','Str 10, Dex 15, Con 12, Int 2, Wis 14, Cha 6','Listen +2, Spot +14',NULL,'Weapon Finesse',NULL,'Temperate mountains','Solitary or pair','1/2',NULL,NULL,'2-3 HD (Medium)','-','','Eagle; CR 1/2; Small animal; HD 1d8+1; hp 5; Init +2; Spd 10 ft. (2 squares), fly 80 ft. (average); AC 14 (+1 size, +2 dex, +1 natural), touch 13, flat-footed 12; Base Atk +0; Grp -4; Atk +3 melee (1d4, talons); Full Atk +3 melee (1d4, 2 talons) and -2 melee (1d4, bite); Space/Reach 5 ft./5 ft.; SA -; SQ Low-light vision; AL N; SV Fort +3, Ref +4, Will +2; Str 10, Dex 15, Con 12, Int 2, Wis 14, Cha 6\n\nSkills and Feats: Listen +2, Spot +14; Weapon Finesse','\n      <div topic=\"Eagle\" level=\"2\"><p><h2>Eagle</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Eagle</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Small Animal<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>1d8+1 (5 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>10 ft. (2 squares), fly 80 ft. (average)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>14 (+1 size, +2 Dex, +1 natural), touch 13, flat-footed 12<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+0/-4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Talons +3 melee (1d4)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>2 talons +3 melee (1d4) and bite -2 melee (1d4)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>5 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Low-light vision<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +3, Ref +4, Will +2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 10, Dex 15, Con 12, Int 2, Wis 14, Cha 6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Listen +2, Spot +14<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Weapon Finesse<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Temperate mountains<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary or pair<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>1/2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>2-3 HD (Medium)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>These birds of prey inhabit nearly every terrain and climate, though they all prefer high, secluded nesting spots.</p><p>A typical eagle is about 3 feet long and has a wingspan of about 7 feet. The statistics presented here can describe any similar-sized, diurnal bird of prey.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Eagles dive at prey, raking with their powerful talons.</p><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> Eagles have a +8 racial bonus on Spot checks.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersAnimals');
INSERT INTO monster VALUES (101,'Elephant','Elephant',NULL,'Huge','Animal',NULL,'11d8+55 (104 hp)','+0','40 ft. (8 squares)','15 (-2 size, +7 natural), touch 8, flat-footed 15','+8','+26','Gore +16 melee (2d8+15)','Slam +16 melee (2d6+10) and 2 stamps +11 melee (2d6+5); or gore +16 melee (2d8+15)','15 ft.','10 ft.','Trample 2d8+15','Low-light vision, scent','Fort +12, Ref +7, Will +6','Str 30, Dex 10, Con 21, Int 2, Wis 13, Cha 7','Listen +12, Spot +10',NULL,'Alertness, Endurance, Iron Will, Skill Focus (Listen)',NULL,'Warm plains','Solitary or herd (6-30)','7',NULL,NULL,'12-22 HD (Huge)','-','Trample (Ex)','Elephant; CR 7; Huge animal; HD 11d8+55; hp 104; Init +0; Spd 40 ft. (8 squares); AC 15 (-2 size, +7 natural), touch 8, flat-footed 15; Base Atk +8; Grp +26; Atk +16 melee (2d8+15, gore); Full Atk +16 melee (2d6+10, slam) and +11 melee (2d6+5, 2 stamps) or +16 melee (2d8+15, gore); Space/Reach 15 ft./10 ft.; SA Trample 2d8+15; SQ Low-light vision, scent; AL N; SV Fort +12, Ref +7, Will +6; Str 30, Dex 10, Con 21, Int 2, Wis 13, Cha 7\n\nSkills and Feats: Listen +12, Spot +10; Alertness, Endurance, Iron Will, Skill Focus (Listen)','\n      <div topic=\"Elephant\" level=\"2\"><p><h2>Elephant</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Elephant</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Huge Animal<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>11d8+55 (104 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+0<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>40 ft. (8 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>15 (-2 size, +7 natural), touch 8, flat-footed 15<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+8/+26<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Gore +16 melee (2d8+15)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Slam +16 melee (2d6+10) and 2 stamps +11 melee (2d6+5); or gore +16 melee (2d8+15)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>15 ft./10 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Trample 2d8+15<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Low-light vision, scent<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +12, Ref +7, Will +6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 30, Dex 10, Con 21, Int 2, Wis 13, Cha 7<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Listen +12, Spot +10<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Alertness, Endurance, Iron Will, Skill Focus (Listen)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Warm plains<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary or herd (6-30)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>7<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>12-22 HD (Huge)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>Massive herbivores of tropical lands, elephants are unpredictable creatures but nevertheless are sometimes used as mounts or beasts of burden.</p><p>This entry describes an African elephant. Indian elephants are slightly smaller and weaker (Strength 28), but more readily trained (Wisdom 15). These statistics can also represent prehistoric creatures such as mammoths and mastodons.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Elephants tend to charge at threatening creatures.</p><div topic=\"Trample\" level=\"8\"><p><b>Trample (Ex):</b> Reflex half DC 25. The save DC is Strength-based.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersAnimals');
INSERT INTO monster VALUES (102,'Hawk','Hawk',NULL,'Tiny','Animal',NULL,'1d8 (4 hp)','+3','10 ft. (2 squares), fly 60 ft. (average)','17 (+2 size, +3 Dex, +2 natural), touch 15, flat-footed 14','+0','-10','Talons +5 melee (1d4-2)','Talons +5 melee (1d4-2)','2-1/2 ft.','0 ft.','-','Low-light vision','Fort +2, Ref +5, Will +2','Str 6, Dex 17, Con 10, Int 2, Wis 14, Cha 6','Listen +2, Spot +14',NULL,'Weapon Finesse',NULL,'Temperate forests','Solitary or pair','1/3',NULL,NULL,'-','-','','Hawk; CR 1/3; Tiny animal; HD 1d8; hp 4; Init +3; Spd 10 ft. (2 squares), fly 60 ft. (average); AC 17 (+2 size, +3 dex, +2 natural), touch 15, flat-footed 14; Base Atk +0; Grp -10; Atk +5 melee (1d4-2, talons); Full Atk +5 melee (1d4-2, talons); Space/Reach 2-1/2 ft./0 ft.; SA -; SQ Low-light vision; AL N; SV Fort +2, Ref +5, Will +2; Str 6, Dex 17, Con 10, Int 2, Wis 14, Cha 6\n\nSkills and Feats: Listen +2, Spot +14; Weapon Finesse','\n      <div topic=\"Hawk\" level=\"2\"><p><h2>Hawk</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Hawk</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Tiny Animal<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>1d8 (4 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>10 ft. (2 squares), fly 60 ft. (average)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>17 (+2 size, +3 Dex, +2 natural), touch 15, flat-footed 14<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+0/-10<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Talons +5 melee (1d4-2)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Talons +5 melee (1d4-2)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>2-1/2 ft./0 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Low-light vision<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +2, Ref +5, Will +2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 6, Dex 17, Con 10, Int 2, Wis 14, Cha 6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Listen +2, Spot +14<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Weapon Finesse<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Temperate forests<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary or pair<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>1/3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>These creatures are similar to eagles but slightly smaller: 1 to 2 feet long, with wingspans of 6 feet or less.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Hawks combine both talons into a single attack.</p><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> Hawks have a +8 racial bonus on Spot checks.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersAnimals');
INSERT INTO monster VALUES (103,'Horse','Horse, Heavy',NULL,'Large','Animal',NULL,'3d8+6 (19 hp)','+1','50 ft. (10 squares)','13 (-1 size, +1 Dex, +3 natural), touch 10, flat-footed 12','+2','+9','Hoof -1 melee (1d6+1*)','2 hooves -1 melee (1d6+1*)','10 ft.','5 ft.','-','Low-light vision, scent','Fort +5, Ref +4, Will +2','Str 16, Dex 13, Con 15, Int 2, Wis 12, Cha 6','Listen +4, Spot +4',NULL,'Endurance, Run',NULL,'Temperate plains','Domesticated','1',NULL,NULL,'-','-','','Heavy horse; CR 1; Large animal; HD 3d8+6; hp 19; Init +1; Spd 50 ft. (10 squares); AC 13 (-1 size, +1 dex, +3 natural), touch 10, flat-footed 12; Base Atk +2; Grp +9; Atk -1 melee (1d6+1*, hoof); Full Atk -1 melee (1d6+1*, 2 hooves); Space/Reach 10 ft./5 ft.; SA -; SQ Low-light vision, scent; AL N; SV Fort +5, Ref +4, Will +2; Str 16, Dex 13, Con 15, Int 2, Wis 12, Cha 6\n\nSkills and Feats: Listen +4, Spot +4; Endurance, Run','\n      <div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>A horse not trained for war does not normally use its hooves to attack. Its hoof attack is treated as a secondary attack and adds only half the horse\'s Strength bonus to damage. (These secondary attacks are noted with an asterisk in the Attack and Full Attack entries for the heavy horse and the light horse.)</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Horse, Heavy<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Large Animal<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>3d8+6 (19 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>50 ft. (10 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>13 (-1 size, +1 Dex, +3 natural), touch 10, flat-footed 12<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+2/+9<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Hoof -1 melee (1d6+1*)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>2 hooves -1 melee (1d6+1*)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>10 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Low-light vision, scent<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +5, Ref +4, Will +2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 16, Dex 13, Con 15, Int 2, Wis 12, Cha 6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Listen +4, Spot +4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Endurance, Run<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Temperate plains<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Domesticated<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>The statistics presented here describe large breeds of working horses such as Clydesdales. These animals are usually ready for heavy work by age three. A heavy horse cannot fight while carrying a rider.</p><div topic=\"Carrying Capacity\" level=\"8\"><p><b>Carrying Capacity:</b> A light load for a heavy horse is up to 200 pounds; a medium load, 201-400 pounds; and a heavy load, 401-600 pounds. A heavy horse can drag 3,000 pounds.</p><p/><p>The statistics presented here describe smaller breeds of working horses such as quarter horses and Arabians as well as wild horses. These animals are usually ready for useful work by age two. A light horse cannot fight while carrying a rider.</p>\n</div><div topic=\"Carrying Capacity\" level=\"8\"><p><b>Carrying Capacity:</b> A light load for a light horse is up to 150 pounds; a medium load, 151-300 pounds; and a heavy load, 301-450 pounds. A light horse can drag 2,250 pounds.</p><p/><p>These animals are similar to heavy horses but are trained and bred for strength and aggression. A heavy warhorse can fight while carrying a rider, but the rider cannot also attack unless he or she succeeds on a Ride check.</p>\n</div><div topic=\"Carrying Capacity\" level=\"8\"><p><b>Carrying Capacity:</b> A light load for a heavy warhorse is up to 300 pounds; a medium load, 301-600 pounds; and a heavy load, 601-900 pounds. A heavy warhorse can drag 4,500 pounds.</p><p/><p>These animals or similar to light horses but are trained and bred for strength and aggression. They usually are not ready for warfare before age three. A light warhorse can fight while carrying a rider, but the rider cannot also attack unless he or she succeeds on a Ride check.</p>\n</div><div topic=\"Carrying Capacity\" level=\"8\"><p><b>Carrying Capacity:</b> A light load for a light warhorse is up to 230 pounds; a medium load, 231-460 pounds; and a heavy load, 461-690 pounds. A light warhorse can drag 3,450 pounds.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 MonstersAnimals');
