INSERT INTO monster VALUES (133,'Snake','Snake, Huge Viper',NULL,'Huge','Animal',NULL,'6d8+6 (33 hp)','+6','20 ft. (4 squares), climb 20 ft., swim 20 ft.','15 (-2 size, +2 Dex, +5 natural), touch 10, flat-footed 15','+4','+15','Bite +6 melee (1d6+4 plus poison)','Bite +6 melee (1d6+4 plus poison)','15 ft.','10 ft.','Poison','Scent','Fort +6, Ref +7, Will +3','Str 16, Dex 15, Con 13, Int 1, Wis 12, Cha 2','Balance +10, Climb +11, Hide +3, Listen +7, Spot +7, Swim +11',NULL,'Improved Initiative, Run, Weapon Focus (bite)',NULL,'Temperate marshes','Solitary','3',NULL,NULL,'7-18 HD (Huge)','-','Constrict (Ex), Improved Grab (Ex)','Huge viper snake; CR 3; Huge animal; HD 6d8+6; hp 33; Init +6; Spd 20 ft. (4 squares), climb 20 ft., swim 20 ft.; AC 15 (-2 size, +2 dex, +5 natural), touch 10, flat-footed 15; Base Atk +4; Grp +15; Atk +6 melee (1d6+4 plus poison, bite); Full Atk +6 melee (1d6+4 plus poison, bite); Space/Reach 15 ft./10 ft.; SA Poison; SQ Scent; AL N; SV Fort +6, Ref +7, Will +3; Str 16, Dex 15, Con 13, Int 1, Wis 12, Cha 2\n\nSkills and Feats: Balance +10, Climb +11, Hide +3, Listen +7, Spot +7, Swim +11; Improved Initiative, Run, Weapon Focus (bite)','\n      <div topic=\"Viper Snake\" level=\"5\"><p><h5>Viper Snake</h5></p><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n\n\n<td><b>Snake, Huge Viper</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n\n\n<td>Huge Animal<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n\n\n<td>6d8+6 (33 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n\n\n<td>+6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n\n\n<td>20 ft. (4 squares), climb 20 ft., swim 20 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n\n\n<td>15 (-2 size, +2 Dex, +5 natural), touch 10, flat-footed 15<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n\n\n<td>+4/+15<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n\n\n<td>Bite +6 melee (1d6+4 plus poison)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n\n\n<td>Bite +6 melee (1d6+4 plus poison)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n\n\n<td>15 ft./10 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n\n\n<td>Poison<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n\n\n<td>Scent<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n\n\n<td>Fort +6, Ref +7, Will +3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n\n\n<td>Str 16, Dex 15, Con 13, Int 1, Wis 12, Cha 2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n\n\n<td>Balance +10, Climb +11, Hide +3, Listen +7, Spot +7, Swim +11<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n\n\n<td>Improved Initiative, Run, Weapon Focus (bite)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n\n\n<td>Temperate marshes<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n\n\n<td>Solitary<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n\n\n<td>3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n\n\n<td>7-18 HD (Huge)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n\n\n<td>-<br/></td>\n\n</tr>\n</table><p>These creatures range widely in size. They are not particularly aggressive, but will often lash out with a bite attack before attempting to retreat.</p>\n</div>\n    ','SRD 3.5 MonstersAnimals');
INSERT INTO monster VALUES (134,'Squid','Squid',NULL,'Medium','Animal','Aquatic','3d8 (13 hp)','+3','Swim 60 ft. (12 squares)','16 (+3 Dex, +3 natural), touch 13, flat-footed 13','+2','+8*','Arms +4 melee (0)','Arms +4 melee (0) and bite -1 melee (1d6+1)','5 ft.','5 ft.','Improved grab','Ink cloud, jet, low-light vision','Fort +3, Ref +6, Will +2','Str 14, Dex 17, Con 11, Int 1, Wis 12, Cha 2','Listen +7, Spot +7, Swim +10',NULL,'Alertness, Endurance',NULL,'Temperate aquatic','Solitary or school (6-11)','1',NULL,NULL,'4-6 HD (Medium); 7-11 HD (Large)','-','Improved Grab (Ex), Ink Cloud (Ex), Jet (Ex)','Squid; CR 1; Medium animal (aquatic); HD 3d8; hp 13; Init +3; Spd Swim 60 ft. (12 squares); AC 16 (+3 dex, +3 natural), touch 13, flat-footed 13; Base Atk +2; Grp +8*; Atk +4 melee (0, arms); Full Atk +4 melee (0, arms) and -1 melee (1d6+1, bite); Space/Reach 5 ft./5 ft.; SA Improved grab; SQ Ink cloud, jet, low-light vision; AL N; SV Fort +3, Ref +6, Will +2; Str 14, Dex 17, Con 11, Int 1, Wis 12, Cha 2\n\nSkills and Feats: Listen +7, Spot +7, Swim +10; Alertness, Endurance','\n      <div topic=\"Squid\" level=\"2\"><p><h2>Squid</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Squid</b><br/></td> \n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Medium Animal (Aquatic)<br/></td> \n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>3d8 (13 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>Swim 60 ft. (12 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>16 (+3 Dex, +3 natural), touch 13, flat-footed 13<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+2/+8*<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Arms +4 melee (0)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Arms +4 melee (0) and bite -1 melee (1d6+1)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>5 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Improved grab<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Ink cloud, jet, low-light vision<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +3, Ref +6, Will +2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 14, Dex 17, Con 11, Int 1, Wis 12, Cha 2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Listen +7, Spot +7, Swim +10<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Alertness, Endurance<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Temperate aquatic<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary or school (6-11)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>4-6 HD (Medium); 7-11 HD (Large)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>These free-swimming mollusks are fairly aggressive. They are more feared than sharks in some locales.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><div topic=\"Improved Grab\" level=\"8\"><p><b>Improved Grab (Ex):</b> To use this ability, a squid must hit an opponent of any size with its arms attack. It can then attempt to start a grapple as a free action without provoking an attack of opportunity. If it wins the grapple check, it establishes a hold and automatically deals bite damage. *A squid has a +4 racial bonus on grapple checks.</p>\n</div><div topic=\"Ink Cloud\" level=\"8\"><p><b>Ink Cloud (Ex):</b> A squid can emit a cloud of jet-black ink 10 feet high by 10 feet wide by 10 feet long once per minute as a free action. The cloud provides total concealment, which the squid normally uses to escape a losing fight. All vision within the cloud is obscured.</p>\n</div><div topic=\"Jet\" level=\"8\"><p><b>Jet (Ex):</b> A squid can jet backward once per round as a full-round action, at a speed of 240 feet. It must move in a straight line, but does not provoke attacks of opportunity while jetting.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> A squid has a +8 racial bonus on any Swim check to perform some special action or avoid a hazard. It can always choose to take 10 on a Swim check, even if distracted or endangered. It can use the run action while swimming, provided it swims in a straight line</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersAnimals');
INSERT INTO monster VALUES (135,'Squid, Giant','Squid, Giant',NULL,'Huge','Animal','Aquatic','12d8+18 (72 hp)','+3','Swim 80 ft. (16 squares)','17 (-2 size, +3 Dex, +6 natural), touch 11, flat-footed 14','+9','+29','Tentacle +15 melee (1d6+8)','10 tentacles +15 melee (1d6+8) and bite +10 melee (2d8+4)','15 ft.','15 ft. (30 ft. with tentacle)','Constrict 1d6+8, improved grab','Ink cloud, jet, low-light vision','Fort +9, Ref +11, Will +5','Str 26, Dex 17, Con 13, Int 1, Wis 12, Cha 2','Listen +10, Spot +11, Swim +16',NULL,'Alertness, Diehard, Endurance, Toughness (2)',NULL,'Temperate aquatic','Solitary','9',NULL,NULL,'13-18 HD (Huge); 19-36 HD (Gargantuan)','-','Constrict (Ex), Improved Grab (Ex), Ink Cloud (Ex), Jet (Ex)','Giant squid; CR 9; Huge animal (aquatic); HD 12d8+18; hp 72; Init +3; Spd Swim 80 ft. (16 squares); AC 17 (-2 size, +3 dex, +6 natural), touch 11, flat-footed 14; Base Atk +9; Grp +29; Atk +15 melee (1d6+8, tentacle); Full Atk +15 melee (1d6+8, 10 tentacles) and +10 melee (2d8+4, bite); Space/Reach 15 ft./15 ft. (30 ft. with tentacle); SA Constrict 1d6+8, improved grab; SQ Ink cloud, jet, low-light vision; AL N; SV Fort +9, Ref +11, Will +5; Str 26, Dex 17, Con 13, Int 1, Wis 12, Cha 2\n\nSkills and Feats: Listen +10, Spot +11, Swim +16; Alertness, Diehard, Endurance, Toughness (2)','\n      <div topic=\"Squid, Giant\" level=\"2\"><p><h2>Squid, Giant</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Squid, Giant</b><br/></td> \n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Huge Animal (Aquatic)<br/></td> \n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>12d8+18 (72 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>Swim 80 ft. (16 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>17 (-2 size, +3 Dex, +6 natural), touch 11, flat-footed 14<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+9/+29<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Tentacle +15 melee (1d6+8)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>10 tentacles +15 melee (1d6+8) and bite +10 melee (2d8+4)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>15 ft./15 ft. (30 ft. with tentacle)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Constrict 1d6+8, improved grab<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Ink cloud, jet, low-light vision<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +9, Ref +11, Will +5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 26, Dex 17, Con 13, Int 1, Wis 12, Cha 2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Listen +10, Spot +11, Swim +16<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Alertness, Diehard, Endurance, Toughness (2)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Temperate aquatic<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>9<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>13-18 HD (Huge); 19-36 HD (Gargantuan)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>These voracious creatures can have bodies more than 20 feet long and attack almost anything they meet.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>An opponent can attack a giant squid\'s tentacles with a sunder attempt as if they were weapons. A giant squid\'s tentacles have 10 hit points each. If a giant squid is currently grappling a target with the tentacle that is being attacked, it usually uses another limb to make its attack of opportunity against the opponent making the sunder attempt. Severing one of a giant squid\'s tentacles deals 5 points of damage to the creature. A giant squid usually withdraws from combat if it loses five tentacles. The creature regrows severed limbs in 1d10+10 days.</p><div topic=\"Constrict\" level=\"8\"><p><b>Constrict (Ex):</b> A giant squid deals 1d6+8 points of damage with a successful grapple check.</p>\n</div><div topic=\"Improved Grab\" level=\"8\"><p><b>Improved Grab (Ex):</b> To use this ability, a giant squid must hit an opponent of any size with a tentacle attack. It can then attempt to start a grapple as a free action without provoking an attack of opportunity. If it wins the grapple check, it establishes a hold and can constrict. *A giant squid has a +4 racial bonus on grapple checks.</p>\n</div><div topic=\"Ink Cloud\" level=\"8\"><p><b>Ink Cloud (Ex):</b> A giant squid can emit a cloud of jet-black ink 20 feet high by 20 feet wide by 20 feet long once per minute as a free action. The cloud provides total concealment, which the squid normally uses to escape a losing fight. All vision within the cloud is obscured.</p>\n</div><div topic=\"Jet\" level=\"8\"><p><b>Jet (Ex):</b> A giant squid can jet backward once per round as a full-round action, at a speed of 320 feet. It must move in a straight line, but does not provoke attacks of opportunity while jetting.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> A giant squid has a +8 racial bonus on any Swim check to perform some special action or avoid a hazard. It can always choose to take 10 on a Swim check, even if distracted or endangered. It can use the run action while swimming, provided it swims in a straight line.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersAnimals');
INSERT INTO monster VALUES (136,'Tiger','Tiger',NULL,'Large','Animal',NULL,'6d8+18 (45 hp)','+2','40 ft. (8 squares)','14 (-1 size, +2 Dex, +3 natural), touch 11, flat-footed 12','+4','+14','Claw +9 melee (1d8+6)','2 claws +9 melee (1d8+6) and bite +4 melee (2d6+3)','10 ft.','5 ft.','Improved grab, pounce, rake 1d8+3','Low-light vision, scent','Fort +8, Ref +7, Will +3','Str 23, Dex 15, Con 17, Int 2, Wis 12, Cha 6','Balance +6, Hide +3*, Listen +3, Move Silently +9, Spot +3, Swim +11',NULL,'Alertness, Improved Natural Weapon (bite), and Improved Natural Weapon (claw).',NULL,'Warm forests','Solitary','4',NULL,NULL,'7-12 HD (Large); 13-18 HD (Huge)','-','Improved Grab (Ex), Pounce (Ex), Rake (Ex)','Tiger; CR 4; Large animal; HD 6d8+18; hp 45; Init +2; Spd 40 ft. (8 squares); AC 14 (-1 size, +2 dex, +3 natural), touch 11, flat-footed 12; Base Atk +4; Grp +14; Atk +9 melee (1d8+6, claw); Full Atk +9 melee (1d8+6, 2 claws) and +4 melee (2d6+3, bite); Space/Reach 10 ft./5 ft.; SA Improved grab, pounce, rake 1d8+3; SQ Low-light vision, scent; AL N; SV Fort +8, Ref +7, Will +3; Str 23, Dex 15, Con 17, Int 2, Wis 12, Cha 6\n\nSkills and Feats: Balance +6, Hide +3*, Listen +3, Move Silently +9, Spot +3, Swim +11; Alertness, Improved Natural Weapon (bite), and Improved Natural Weapon (claw).','\n      <div topic=\"Tiger\" level=\"2\"><p><h2>Tiger</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Tiger</b><br/></td> \n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Large Animal<br/></td> \n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>6d8+18 (45 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>40 ft. (8 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>14 (-1 size, +2 Dex, +3 natural), touch 11, flat-footed 12<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+4/+14<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Claw +9 melee (1d8+6)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>2 claws +9 melee (1d8+6) and bite +4 melee (2d6+3)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>10 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Improved grab, pounce, rake 1d8+3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Low-light vision, scent<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +8, Ref +7, Will +3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 23, Dex 15, Con 17, Int 2, Wis 12, Cha 6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Balance +6, Hide +3*, Listen +3, Move Silently +9, Spot +3, Swim +11<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Alertness, Improved Natural Weapon (bite), and Improved Natural Weapon (claw).<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Warm forests<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>7-12 HD (Large); 13-18 HD (Huge)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>These great cats stand more than 3 feet tall at the shoulder and are about 9 feet long. They weigh from 400 to 600 pounds.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><div topic=\"Improved Grab\" level=\"8\"><p><b>Improved Grab (Ex):</b> To use this ability, a tiger must hit with a claw or bite attack. It can then attempt to start a grapple as a free action without provoking an attack of opportunity. If it wins the grapple check, it establishes a hold and can rake.</p>\n</div><div topic=\"Pounce\" level=\"8\"><p><b>Pounce (Ex):</b> If a tiger charges a foe, it can make a full attack, including two rake attacks.</p>\n</div><div topic=\"Rake\" level=\"8\"><p><b>Rake (Ex):</b> Attack bonus +9 melee, damage 1d8+3.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> Tigers have a +4 racial bonus on Balance, Hide, and Move Silently checks. *In areas of tall grass or heavy undergrowth, the Hide bonus improves to +8.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersAnimals');
INSERT INTO monster VALUES (137,'Toad','Toad',NULL,'Diminutive','Animal',NULL,'1/4 d8 (1 hp)','+1','5 ft. (1 square)','15 (+4 size, +1 Dex), touch 15, flat-footed 14','+0','-17','-','-','1 ft.','0 ft.','-','Amphibious, low-light vision','Fort +2, Ref +3, Will +2','Str 1, Dex 12, Con 11, Int 1, Wis 14, Cha 4','Hide +21, Listen +4, Spot +4',NULL,'Alertness',NULL,'Temperate marshes','Swarm (10-100)','1/10',NULL,NULL,'-','-','','Toad; CR 1/10; Diminutive animal; HD 1/4 d8; hp 1; Init +1; Spd 5 ft. (1 square); AC 15 (+4 size, +1 dex), touch 15, flat-footed 14; Base Atk +0; Grp -17; Atk -; Full Atk -; Space/Reach 1 ft./0 ft.; SA -; SQ Amphibious, low-light vision; AL N; SV Fort +2, Ref +3, Will +2; Str 1, Dex 12, Con 11, Int 1, Wis 14, Cha 4\n\nSkills and Feats: Hide +21, Listen +4, Spot +4; Alertness','\n      <div topic=\"Toad\" level=\"2\"><p><h2>Toad</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Toad</b><br/></td> \n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Diminutive Animal<br/></td> \n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>1/4 d8 (1 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>5 ft. (1 square)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>15 (+4 size, +1 Dex), touch 15, flat-footed 14<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+0/-17<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>1 ft./0 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Amphibious, low-light vision<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +2, Ref +3, Will +2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 1, Dex 12, Con 11, Int 1, Wis 14, Cha 4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Hide +21, Listen +4, Spot +4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Alertness<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Temperate marshes<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Swarm (10-100)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>1/10<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>These diminutive amphibians are innocuous and beneficial, since they eat insects.</p><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> A toad\'s coloration gives it a +4 racial bonus on Hide checks.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 MonstersAnimals');
INSERT INTO monster VALUES (138,'Weasel','Weasel',NULL,'Tiny','Animal',NULL,'1/2 d8 (2 hp)','+2','20 ft. (4 squares), climb 20 ft.','14 (+2 size, +2 Dex), touch 14, flat-footed 12','+0','-12','Bite +4 melee (1d3-4)','Bite +4 melee (1d3-4)','2-1/2 ft.','0 ft.','Attach','Low-light vision, scent','Fort +2, Ref +4, Will +1','Str 3, Dex 15, Con 10, Int 2, Wis 12, Cha 5','Balance +10, Climb +10, Hide +11, Move Silently +8, Spot +3',NULL,'Weapon Finesse',NULL,'Temperate hills','Solitary','1/4',NULL,NULL,'-','-','Attach (Ex)','Weasel; CR 1/4; Tiny animal; HD 1/2 d8; hp 2; Init +2; Spd 20 ft. (4 squares), climb 20 ft.; AC 14 (+2 size, +2 dex), touch 14, flat-footed 12; Base Atk +0; Grp -12; Atk +4 melee (1d3-4, bite); Full Atk +4 melee (1d3-4, bite); Space/Reach 2-1/2 ft./0 ft.; SA Attach; SQ Low-light vision, scent; AL N; SV Fort +2, Ref +4, Will +1; Str 3, Dex 15, Con 10, Int 2, Wis 12, Cha 5\n\nSkills and Feats: Balance +10, Climb +10, Hide +11, Move Silently +8, Spot +3; Weapon Finesse','\n      <div topic=\"Weasel\" level=\"2\"><p><h2>Weasel</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Weasel</b><br/></td> \n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Tiny Animal<br/></td> \n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>1/2 d8 (2 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>20 ft. (4 squares), climb 20 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>14 (+2 size, +2 Dex), touch 14, flat-footed 12<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+0/-12<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Bite +4 melee (1d3-4)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Bite +4 melee (1d3-4)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>2-1/2 ft./0 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Attach<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Low-light vision, scent<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +2, Ref +4, Will +1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 3, Dex 15, Con 10, Int 2, Wis 12, Cha 5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Balance +10, Climb +10, Hide +11, Move Silently +8, Spot +3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Weapon Finesse<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Temperate hills<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>1/4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>These little mammals are aggressive predators but usually confine themselves to smaller prey. The statistics presented here can also apply to ferrets.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><div topic=\"Attach\" level=\"8\"><p><b>Attach (Ex):</b> If a weasel hits with a bite attack, it uses its powerful jaws to latch onto the opponent\'s body and automatically deals bite damage each round it remains attached. An attached weasel loses its Dexterity bonus to Armor Class and has an AC of 12. An attached weasel can be struck with a weapon or grappled itself. To remove an attached weasel through grappling, the opponent must achieve a pin against the creature.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> Weasels have a +4 racial bonus on Move Silently checks and a +8 racial bonus on Balance and Climb checks. They use their Dexterity modifier for Climb checks. A weasel can always choose to take 10 on a Climb check, even if rushed or threatened.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersAnimals');
INSERT INTO monster VALUES (139,'Whale','Baleen Whale',NULL,'Gargantuan','Animal',NULL,'12d8+78 (132 hp)','+1','Swim 40 ft. (8 squares)','16 (-4 size, +1 Dex, +9 natural), touch 7, flat-footed 15','+9','+33','Tail slap +17 melee (1d8+18)','Tail slap +17 melee (1d8+18)','20 ft.','15 ft.','-','Blindsight 120 ft., hold breath, low-light vision','Fort +14, Ref +9, Will +5','Str 35, Dex 13, Con 22, Int 2, Wis 12, Cha 6','Listen +15*, Spot +14*, Swim +20',NULL,'Alertness, Diehard, Endurance, Toughness (2)',NULL,'Warm aquatic','Solitary','6',NULL,NULL,'13-18 HD (Gargantuan); 19-36 HD (Colossal)','-','Blindsight (Ex), Hold Breath (Ex)','Baleen whale; CR 6; Gargantuan animal; HD 12d8+78; hp 132; Init +1; Spd Swim 40 ft. (8 squares); AC 16 (-4 size, +1 dex, +9 natural), touch 7, flat-footed 15; Base Atk +9; Grp +33; Atk +17 melee (1d8+18, tail slap); Full Atk +17 melee (1d8+18, tail slap); Space/Reach 20 ft./15 ft.; SA -; SQ Blindsight 120 ft., hold breath, low-light vision; AL N; SV Fort +14, Ref +9, Will +5; Str 35, Dex 13, Con 22, Int 2, Wis 12, Cha 6\n\nSkills and Feats: Listen +15*, Spot +14*, Swim +20; Alertness, Diehard, Endurance, Toughness (2)','\n      <div topic=\"Whale\" level=\"2\"><p><h2>Whale</h2></p><p>Some varieties of these seagoing mammals are among the largest animals known. Relatively small whales (such as the orca presented here) can be vicious predators, attacking virtually anything they detect.</p><div topic=\"Blindsight\" level=\"8\"><p><b>Blindsight (Ex):</b> Whales can \'see\' by emitting high-frequency sounds, inaudible to most other creatures, that allow them to locate objects and creatures within 120 feet. A <i>silence</i> spell negates this and forces the whale to rely on its vision, which is approximately as good as a human\'s.</p>\n</div><div topic=\"Hold Breath\" level=\"8\"><p><b>Hold Breath (Ex):</b> A whale can hold its breath for a number of rounds equal to 8 x ?its Constitution score before it risks drowning.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> A whale has a +8 racial bonus on any Swim check to perform some special action or avoid a hazard. It can always choose to take 10 on a Swim check, even if distracted or endangered. It can use the run action while swimming, provided it swims in a straight line. *A whale has a +4 racial bonus on Spot and Listen checks. These bonuses are lost if its blindsight is negated.</p><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Baleen Whale<br/></td> \n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Gargantuan Animal<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>12d8+78 (132 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>Swim 40 ft. (8 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>16 (-4 size, +1 Dex, +9 natural), touch 7, flat-footed 15<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+9/+33<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Tail slap +17 melee (1d8+18)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Tail slap +17 melee (1d8+18)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>20 ft./15 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Blindsight 120 ft., hold breath, low-light vision<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +14, Ref +9, Will +5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 35, Dex 13, Con 22, Int 2, Wis 12, Cha 6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Listen +15*, Spot +14*, Swim +20<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Alertness, Diehard, Endurance, Toughness (2)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Warm aquatic<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>13-18 HD (Gargantuan); 19-36 HD (Colossal)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>The statistics here describe a plankton-feeding whale between 30 and 60 feet long, such as gray, humpback, and right whales. These massive creatures are surprisingly gentle. If harassed or provoked, they are as likely to flee as they are to retaliate.</p><p/><p>Also known as sperm whales, these creatures can be up to 60 feet long. They prey on giant squids.</p><p/><p>These ferocious creatures are about 30 feet long. They eat fish, squid, seals, and other whales.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 MonstersAnimals');
INSERT INTO monster VALUES (140,'Whale','Cachalot Whale',NULL,'Gargantuan','Animal',NULL,'12d8+87 (141 hp)','+1','Swim 40 ft. (8 squares)','16 (-4 size, +1 Dex, +9 natural), touch 7, flat-footed 15','+9','+33','Bite +17 melee (4d6+12)','Bite +17 melee (4d6+12) and tail slap +12 melee (1d8+6)','20 ft.','15 ft.','-','Blindsight 120 ft., hold breath, low-light vision','Fort +15, Ref +9, Will +6','Str 35, Dex 13, Con 24, Int 2, Wis 14, Cha 6','Listen +15*, Spot +14*, Swim +20',NULL,'Alertness, Diehard, Endurance, Improved Natural Attack (bite), Toughness',NULL,'Temperate aquatic','Solitary or pod (6-11)','7',NULL,NULL,'13-18 HD (Gargantuan); 19-36 HD (Colossal)','-','Blindsight (Ex), Hold Breath (Ex)','Cachalot whale; CR 7; Gargantuan animal; HD 12d8+87; hp 141; Init +1; Spd Swim 40 ft. (8 squares); AC 16 (-4 size, +1 dex, +9 natural), touch 7, flat-footed 15; Base Atk +9; Grp +33; Atk +17 melee (4d6+12, bite); Full Atk +17 melee (4d6+12, bite) and +12 melee (1d8+6, tail slap); Space/Reach 20 ft./15 ft.; SA -; SQ Blindsight 120 ft., hold breath, low-light vision; AL N; SV Fort +15, Ref +9, Will +6; Str 35, Dex 13, Con 24, Int 2, Wis 14, Cha 6\n\nSkills and Feats: Listen +15*, Spot +14*, Swim +20; Alertness, Diehard, Endurance, Improved Natural Attack (bite), Toughness','\n      <div topic=\"Whale\" level=\"2\"><p><h2>Whale</h2></p><p>Some varieties of these seagoing mammals are among the largest animals known. Relatively small whales (such as the orca presented here) can be vicious predators, attacking virtually anything they detect.</p><div topic=\"Blindsight\" level=\"8\"><p><b>Blindsight (Ex):</b> Whales can \'see\' by emitting high-frequency sounds, inaudible to most other creatures, that allow them to locate objects and creatures within 120 feet. A <i>silence</i> spell negates this and forces the whale to rely on its vision, which is approximately as good as a human\'s.</p>\n</div><div topic=\"Hold Breath\" level=\"8\"><p><b>Hold Breath (Ex):</b> A whale can hold its breath for a number of rounds equal to 8 x ?its Constitution score before it risks drowning.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> A whale has a +8 racial bonus on any Swim check to perform some special action or avoid a hazard. It can always choose to take 10 on a Swim check, even if distracted or endangered. It can use the run action while swimming, provided it swims in a straight line. *A whale has a +4 racial bonus on Spot and Listen checks. These bonuses are lost if its blindsight is negated.</p><p/><p>The statistics here describe a plankton-feeding whale between 30 and 60 feet long, such as gray, humpback, and right whales. These massive creatures are surprisingly gentle. If harassed or provoked, they are as likely to flee as they are to retaliate.</p><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Cachalot Whale<br/></td> \n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Gargantuan Animal<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>12d8+87 (141 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>Swim 40 ft. (8 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>16 (-4 size, +1 Dex, +9 natural), touch 7, flat-footed 15<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+9/+33<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Bite +17 melee (4d6+12)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Bite +17 melee (4d6+12) and tail slap +12 melee (1d8+6)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>20 ft./15 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Blindsight 120 ft., hold breath, low-light vision<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +15, Ref +9, Will +6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 35, Dex 13, Con 24, Int 2, Wis 14, Cha 6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Listen +15*, Spot +14*, Swim +20<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Alertness, Diehard, Endurance, Improved Natural Attack (bite), Toughness<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Temperate aquatic<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary or pod (6-11)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>7<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>13-18 HD (Gargantuan); 19-36 HD (Colossal)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>Also known as sperm whales, these creatures can be up to 60 feet long. They prey on giant squids.</p><p/><p>These ferocious creatures are about 30 feet long. They eat fish, squid, seals, and other whales.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 MonstersAnimals');
